package br.com.fooddelivery.whatsapp;
import br.com.fooddelivery.catalog.*;
import br.com.fooddelivery.identity.*;
import br.com.fooddelivery.orders.*;
import br.com.fooddelivery.payments.*;
import br.com.fooddelivery.platform.CityMatcher;
import br.com.fooddelivery.settings.*;
import br.com.fooddelivery.admin.AdminAuditService;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import java.time.Instant;
import java.security.SecureRandom;
import java.text.Normalizer;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.core.env.Environment;
@Service
public class WhatsAppCommerce {
 private final WhatsAppBindingRepository bindings;private final WhatsAppSessionRepository sessions;private final WhatsAppEventRepository events;private final WhatsAppReplyRepository replies;private final AccountRepository accounts;private final StoreRepository stores;private final CatalogItemRepository items;private final OrderService orders;private final PaymentRepository payments;private final PrivateCipher cipher;private final IntegrationSettings settings;private final PasswordEncoder encoder;private final ObjectMapper mapper;private final Environment environment;private final AdminAuditService audit;
 public WhatsAppCommerce(WhatsAppBindingRepository bindings,WhatsAppSessionRepository sessions,WhatsAppEventRepository events,WhatsAppReplyRepository replies,AccountRepository accounts,StoreRepository stores,CatalogItemRepository items,OrderService orders,PaymentRepository payments,PrivateCipher cipher,IntegrationSettings settings,PasswordEncoder encoder,ObjectMapper mapper,Environment environment,AdminAuditService audit){this.bindings=bindings;this.sessions=sessions;this.events=events;this.replies=replies;this.accounts=accounts;this.stores=stores;this.items=items;this.orders=orders;this.payments=payments;this.cipher=cipher;this.settings=settings;this.encoder=encoder;this.mapper=mapper;this.environment=environment;this.audit=audit;}
 public boolean enabled(){return Boolean.parseBoolean(setting("WHATSAPP_COMMERCE_ENABLED","false"))&&Boolean.parseBoolean(setting("WHATSAPP_CLOUD_ENABLED","false"));}
 public String setting(String key,String fallback){return settings.value(key,environment.getProperty(key,fallback));}
 public static String normalizePhone(String phone){String p=phone==null?"":phone.replaceAll("\\D","");if(p.length()==10||p.length()==11)p="55"+p;if(!p.matches("[0-9]{12,15}"))throw new IllegalArgumentException("Telefone inválido.");return p;}
 private String hash(String phone){return cipher.fingerprint("WHATSAPP",normalizePhone(phone));}
 @Transactional public Object bind(UUID id,String password){Account a=accounts.findByIdForUpdate(id).orElseThrow();if(!encoder.matches(password,a.getPasswordHash())||!a.isActive())throw new AccessDeniedException("Confirme sua identidade.");if(!a.isPhoneVerified())throw new IllegalStateException("Confirme seu telefone no perfil antes de vincular o WhatsApp.");if(!a.getGrantedRoles().contains(AccountRole.CUSTOMER))throw new AccessDeniedException("É necessário acesso de cliente.");String key=hash(a.getPhone());var existing=bindings.findById(key);if(existing.isPresent()&&!existing.get().accountId.equals(id))throw new IllegalStateException("Este telefone já está vinculado a outra conta. Fale com o atendimento.");bindings.findByAccountId(id).filter(b->!b.phoneHash.equals(key)).ifPresent(b->{sessions.deleteById(b.phoneHash);bindings.delete(b);bindings.flush();});bindings.save(new WhatsAppBinding(key,id,a.getCredentialVersion()));audit.record(id,"WHATSAPP_LINKED","ACCOUNT",id,"Canal de compras vinculado ao telefone confirmado, com consentimento.");return Map.of("linked",true);}
 @Transactional public Object unlink(UUID id,String password){Account a=accounts.findByIdForUpdate(id).orElseThrow();if(!encoder.matches(password,a.getPasswordHash()))throw new AccessDeniedException("Confirme sua identidade.");bindings.findByAccountId(id).ifPresent(b->{sessions.deleteById(b.phoneHash);bindings.delete(b);});audit.record(id,"WHATSAPP_UNLINKED","ACCOUNT",id,"Canal de compras desvinculado.");return Map.of("linked",false);}
 @Transactional(readOnly=true) public Object status(UUID id){return Map.of("linked",bindings.findByAccountId(id).isPresent(),"available",enabled());}
 @Transactional public void accept(String id,String from,String text){if(id==null||id.isBlank()||id.length()>200||text==null||text.isBlank()||text.length()>2000)throw new IllegalArgumentException("Mensagem inválida.");if(events.existsById(id))return;String phone=normalizePhone(from),hash=hash(phone);if(events.countByPhoneHashAndCreatedAtAfter(hash,Instant.now().minusSeconds(60))>=20)return;events.save(new WhatsAppEvent(id,hash,cipher.encrypt("WA_PHONE:"+id,phone),cipher.encrypt("WA_TEXT:"+id,text)));}
 public static class Cart {public UUID storeId;public Map<UUID,Integer> quantities=new LinkedHashMap<>();public String mode="PICKUP";public String confirmation;public long quotedAmount;public Instant quotedUntil;public String quotedAddress;}
 public record Response(String text,UUID paymentId,UUID customerId) {static Response text(String value){return new Response(value,null,null);}}
 @Transactional public void process(String id){var event=events.lock(id).orElseThrow();if(!event.status.equals("PENDING"))return;String phone=cipher.decrypt("WA_PHONE:"+id,event.encryptedPhone),text=cipher.decrypt("WA_TEXT:"+id,event.encryptedText);String key=event.phoneHash;var binding=bindings.findById(key);Response response;
  if(binding.isEmpty())response=Response.text("Bem-vindo ao FoodDelivery. Para comprar por aqui, entre no site, confirme seu telefone e ative Compras pelo WhatsApp em Minha conta > Segurança: "+site()+"/#account");
  else{Account account=accounts.findByIdForUpdate(binding.get().accountId).orElseThrow();if(!account.isActive()||!account.isPhoneVerified()||account.getPhone()==null||!hash(account.getPhone()).equals(key)||account.getCredentialVersion()!=binding.get().credentialVersion||!account.getGrantedRoles().contains(AccountRole.CUSTOMER))response=Response.text("Por segurança, vincule novamente seu WhatsApp na sua conta do site: "+site()+"/#account");
   else{var session=sessions.findById(key);Cart cart=new Cart();if(session.isPresent()&&session.get().updatedAt.isAfter(Instant.now().minusSeconds(1800)))try{cart=mapper.readValue(cipher.decrypt("WA_CART:"+key,session.get().encryptedState),Cart.class);}catch(Exception invalid){throw new IllegalStateException("Não foi possível abrir a conversa protegida.");}
    try{response=answer(account,cart,text);}catch(IllegalArgumentException|IllegalStateException|NoSuchElementException known){response=Response.text("Não foi possível concluir: "+known.getMessage()+" Envie MENU para revisar as opções.");}
    try{sessions.save(new WhatsAppSession(key,cipher.encrypt("WA_CART:"+key,mapper.writeValueAsString(cart))));}catch(Exception invalid){throw new IllegalStateException("Não foi possível guardar a conversa.");}
   }}
  String reply=response.text();if(reply.length()>3600)reply=reply.substring(0,3550)+"\nVeja todas as opções no site: "+site();replies.save(new WhatsAppReply(id,cipher.encrypt("WA_REPLY_PHONE:"+id,phone),cipher.encrypt("WA_REPLY_TEXT:"+id,reply),response.paymentId(),response.customerId()));event.status="DONE";
 }
 private String site(){return environment.getProperty("app.payment.mercadopago.frontend-url","http://127.0.0.1:5180");}
 private static String money(long cents){return String.format(Locale.forLanguageTag("pt-BR"),"R$ %.2f",cents/100.0);}
 private List<Store> available(Account a){return stores.findByActiveTrueAndApprovedTrue().stream().filter(Store::isAvailable).filter(s->CityMatcher.sameCity(a.getCity(),a.getState(),s.getCity(),s.getState())).sorted(Comparator.comparing(Store::getName)).limit(30).toList();}
 private Response answer(Account a,Cart cart,String raw){String[] command=Normalizer.normalize(raw.trim(),Normalizer.Form.NFD).replaceAll("\\p{M}","").toUpperCase(Locale.ROOT).split("\\s+");String action=command[0];
  if(Set.of("MENU","OI","OLA","AJUDA").contains(action))return Response.text("FoodDelivery — comandos:\nLOJAS: estabelecimentos da cidade do seu perfil\nLOJA código: escolher estabelecimento\nCATALOGO: produtos, serviços e preços\nADICIONAR código quantidade\nRETIRADA ou ENTREGA\nCARRINHO: conferir valores\nFINALIZAR: revisar antes de confirmar\nLIMPAR: esvaziar carrinho\nPEDIDOS: acompanhar no site\nVocê só paga pelo checkout seguro. Não envie senhas, cartões ou códigos bancários aqui.");
  if(action.equals("PEDIDOS"))return Response.text("Consulte pedidos, pagamentos, cancelamentos e atendimento na sua conta: "+site()+"/#orders");
  if(action.equals("LOJAS")){StringBuilder b=new StringBuilder("Lojas na cidade do seu perfil:\n");for(Store s:available(a))b.append(s.getId().toString(),0,8).append(" — ").append(s.getName()).append('\n');return Response.text(b+"Envie LOJA seguido do código. Para outra cidade, altere a região no site.");}
  if(action.equals("LIMPAR")){cart.quantities.clear();cart.confirmation=null;return Response.text("Carrinho esvaziado. Envie CATALOGO para continuar.");}
  if(action.equals("LOJA")){if(command.length!=2||!command[1].matches("[A-F0-9-]{8,36}"))return Response.text("Envie LOJA seguido do código mostrado em LOJAS.");var matches=available(a).stream().filter(s->s.getId().toString().toUpperCase(Locale.ROOT).startsWith(command[1])).toList();if(matches.size()!=1)return Response.text("Loja não encontrada ou código ambíguo. Envie LOJAS novamente.");cart.storeId=matches.get(0).getId();cart.quantities.clear();cart.confirmation=null;return Response.text("Loja selecionada: "+matches.get(0).getName()+". Envie CATALOGO para ver opções.");}
  if(cart.storeId==null)return Response.text("Escolha a loja antes. Envie LOJAS.");Store store=stores.findById(cart.storeId).filter(Store::isAvailable).orElseThrow(()->new IllegalStateException("Loja indisponível."));List<CatalogItem> catalog=items.findByStoreIdAndActiveTrue(store.getId());
  if(action.equals("CATALOGO")){StringBuilder b=new StringBuilder(store.getName()+"\n");for(var i:catalog.stream().limit(30).toList())b.append(i.getId().toString(),0,8).append(" — ").append(i.getName()).append(" · ").append(money(i.getPriceCents())).append(i.isServiceItem()?" · serviço: agende no site":" · estoque "+i.getStock()).append('\n');return Response.text(b+"\nADICIONAR código quantidade\nServiços e catálogo completo: "+site()+"/#home");}
  if(action.equals("ADICIONAR")){if(command.length!=3||!command[1].matches("[A-F0-9-]{8,36}")||!command[2].matches("[0-9]{1,2}"))return Response.text("Use ADICIONAR código quantidade. Ex.: ADICIONAR 1234abcd 2.");var matches=catalog.stream().filter(i->i.getId().toString().toUpperCase(Locale.ROOT).startsWith(command[1])).toList();if(matches.size()!=1)return Response.text("Código indisponível ou ambíguo. Envie CATALOGO.");var item=matches.get(0);if(item.isServiceItem())return Response.text("Este serviço precisa de agendamento por horário/profissional. Reserve no site: "+site()+"/#home");int quantity=Integer.parseInt(command[2]),total=Math.addExact(cart.quantities.getOrDefault(item.getId(),0),quantity);if(quantity<1||total>50||total>item.getStock()||cart.quantities.size()>=20&&!cart.quantities.containsKey(item.getId()))return Response.text("Quantidade indisponível ou limite do carrinho atingido.");cart.quantities.put(item.getId(),total);cart.confirmation=null;return Response.text("Produto adicionado. Envie CARRINHO para revisar.");}
  if(action.equals("RETIRADA")||action.equals("ENTREGA")){cart.mode=action.equals("ENTREGA")?"DELIVERY":"PICKUP";cart.confirmation=null;return Response.text("Modalidade selecionada. ENTREGA usa o endereço cadastrado no seu perfil; confira-o no site antes de continuar. Envie CARRINHO.");}
  if(Set.of("CARRINHO","FINALIZAR","CONFIRMAR").contains(action)){if(cart.quantities.isEmpty())return Response.text("Seu carrinho está vazio. Envie CATALOGO.");FulfillmentType mode=FulfillmentType.valueOf(cart.mode);store.requireFulfillment(mode);long amount=mode==FulfillmentType.DELIVERY?store.getDeliveryFeeCents():0;StringBuilder summary=new StringBuilder(store.getName()+" · "+(mode==FulfillmentType.DELIVERY?"Entrega no endereço do perfil":"Retirada na loja")+"\n");for(var entry:cart.quantities.entrySet()){var item=catalog.stream().filter(i->i.getId().equals(entry.getKey())&&!i.isServiceItem()).findFirst().orElseThrow(()->new IllegalStateException("Um produto saiu do catálogo. Limpe e revise o carrinho."));if(entry.getValue()>item.getStock())throw new IllegalStateException("Estoque insuficiente. Limpe e revise o carrinho.");amount=Math.addExact(amount,Math.multiplyExact(item.getPriceCents(),entry.getValue()));summary.append(entry.getValue()).append(" × ").append(item.getName()).append('\n');}summary.append("Total com entrega, quando aplicável: ").append(money(amount));
   String deliveryAddress=mode==FulfillmentType.DELIVERY?java.util.stream.Stream.of(a.getAddressLine(),a.getAddressComplement(),a.getNeighborhood(),a.getCity(),a.getState(),a.getPostalCode()).filter(v->v!=null&&!v.isBlank()).collect(java.util.stream.Collectors.joining(", ")):null;
   if(action.equals("CONFIRMAR")){if(command.length!=2||cart.confirmation==null||!cart.confirmation.equals(command[1])||cart.quotedUntil==null||cart.quotedUntil.isBefore(Instant.now())||cart.quotedAmount!=amount||!Objects.equals(cart.quotedAddress,deliveryAddress)){cart.confirmation=null;return Response.text("Confirmação inválida, expirada ou preço alterado. Envie FINALIZAR e confira novamente.");}String address=deliveryAddress;if(mode==FulfillmentType.DELIVERY&&(address==null||address.isBlank()))return Response.text("Cadastre o endereço de entrega no site antes de continuar.");var requested=cart.quantities.entrySet().stream().map(e->new OrderService.RequestedLine(e.getKey(),e.getValue())).toList();if(!Cpf.isValid(a.getCpf())||a.getPhone()==null||a.getPhone().isBlank())return Response.text("Complete CPF e telefone no perfil do site antes de confirmar o pedido.");var order=orders.create(a.getId(),store.getId(),mode,address,"Pedido confirmado pelo cliente no WhatsApp.",requested);var payment=payments.findByOrderId(order.getId()).orElseThrow();cart.quantities.clear();cart.confirmation=null;return new Response("Pedido "+order.getId().toString().substring(0,8).toUpperCase(Locale.ROOT)+" criado. O pagamento antecipado será feito no checkout seguro; a loja só recebe a confirmação após aprovação do provedor.",payment.getId(),a.getId());}
   if(action.equals("FINALIZAR")){cart.quotedAmount=amount;cart.quotedAddress=deliveryAddress;if(deliveryAddress!=null)summary.append("\nEndereço: ").append(deliveryAddress);cart.confirmation=String.format(Locale.ROOT,"%06d",new SecureRandom().nextInt(1_000_000));cart.quotedUntil=Instant.now().plusSeconds(300);return Response.text(summary+"\nConfira os dados. Para criar o pedido, envie CONFIRMAR "+cart.confirmation+". Válido por cinco minutos. O estoque será conferido novamente.");}return Response.text(summary+"\nEnvie FINALIZAR para revisar a confirmação.");
  }
  return Response.text("Comando não reconhecido. Envie MENU para ver as opções.");
 }
}
